import {
	flushObservability,
	generateFailurePayload,
	ingestFailedPayment,
	initObservability,
	runInvestigation,
} from "@cube/agent";
import { customers, invoices } from "@cube/db";
import { eq } from "drizzle-orm";

import { agentConfig } from "../config";
import { db } from "../services";

const config = { ...agentConfig, autoSend: false };
await initObservability(config);

const [row] = await db
	.select({
		projectId: invoices.projectId,
		customerId: invoices.customerId,
		customerExternalId: customers.externalId,
		customerName: customers.name,
		customerEmail: customers.email,
		invoiceId: invoices.id,
		invoiceNumber: invoices.invoiceNumber,
		totalAmount: invoices.totalAmount,
		currency: invoices.currency,
	})
	.from(invoices)
	.innerJoin(customers, eq(customers.id, invoices.customerId))
	.where(eq(invoices.status, "pending"))
	.limit(1);

if (!row) throw new Error("no pending invoice to test with");

const payload = generateFailurePayload({
	projectId: row.projectId,
	customerId: row.customerId,
	customerExternalId: row.customerExternalId,
	customerName: row.customerName,
	customerEmail: row.customerEmail,
	invoiceId: row.invoiceId,
	invoiceNumber: row.invoiceNumber,
	amountCents: Math.round(Number(row.totalAmount) * 100),
	currency: row.currency,
	declineCode: "insufficient_funds",
	attemptNumber: 1,
});

const result = await ingestFailedPayment(db, payload);
await runInvestigation(db, config, result.investigationId);
await flushObservability();

console.log("INVESTIGATION_ID=" + result.investigationId);
process.exit(0);

