import type { Request, Response } from "express";
import { ENV } from "../env.server";

export const SESSION_COOKIE = ENV.SESSION_COOKIE_NAME;

function parseCookies(header: string | undefined): Record<string,string> {
  const out: Record<string,string> = {};
  if (!header) return out;
  for (const part of header.split(";")) {
    const idx = part.indexOf("=");
    if (idx === -1) continue;
    const k = part.slice(0,idx).trim();
    const v = part.slice(idx+1).trim();
    if (k) out[k] = decodeURIComponent(v);
  }
  return out;
}

export function getSessionCookie(req: Request): string | undefined {
  return parseCookies(req.headers.cookie)[SESSION_COOKIE];
}

export function setSessionCookie(res: Response, token: string, expiresAt: Date) {
  res.cookie(SESSION_COOKIE, token, {
    httpOnly: true,
    sameSite: "lax",
    secure: ENV.NODE_ENV === "production",
    path: "/",
    expires: expiresAt,
  });
}

export function clearSessionCookie(res: Response) {
  res.clearCookie(SESSION_COOKIE, {
    httpOnly: true,
    sameSite: "lax",
    secure: ENV.NODE_ENV === "production",
    path: "/",
  });
}
```

Wait: cookie set by server for cross-origin request. When the browser makes a cross-site request (different port but same site "localhost"), SameSite=Lax should still send it for top-level and same-site requests. Since Next (:3001) and API (:3000) share site localhost, Lax works. But fetch from :3001 to :3000 is same-site (port ignored for SameSite), so cookie sent with credentials include. Good.

However, SameSite=Lax does NOT send cookies on cross-site subrequests (like images/fetch), but same-site is fine. localhost:3001 → localhost:3000 is same-site. Good.

Actually wait, there's nuance: "site" = scheme + registrable domain. localhost has no registrable domain but is treated as same-site for itself across ports. Modern browsers: localhost is its own site. Ports don't matter. So SameSite works.

