import { NextResponse, type NextRequest } from "next/server";

import { SESSION_COOKIE } from "@/lib/session";

const PUBLIC_PATHS = ["/login"];

function isPublic(pathname: string): boolean {
	return PUBLIC_PATHS.some(
		(path) => pathname === path || pathname.startsWith(`${path}/`),
	);
}

/**
 * Cheap, optimistic gate: redirect anonymous users to /login and bounce
 * signed-in users away from /login. The API still validates the session on
 * every request, so a stale cookie cannot access data.
 */
export function middleware(request: NextRequest) {
	const { pathname } = request.nextUrl;
	const hasSession = request.cookies.has(SESSION_COOKIE);

	if (!hasSession && !isPublic(pathname)) {
		const url = request.nextUrl.clone();
		url.pathname = "/login";
		url.search = "";
		if (pathname !== "/") url.searchParams.set("next", pathname);
		return NextResponse.redirect(url);
	}

	if (hasSession && pathname === "/login") {
		const url = request.nextUrl.clone();
		url.pathname = "/";
		url.search = "";
		return NextResponse.redirect(url);
	}

	return NextResponse.next();
}

export const config = {
	matcher: [
		"/((?!_next/static|_next/image|favicon.ico|.*\\.(?:svg|png|jpg|jpeg|gif|webp|ico)$).*)",
	],
};

"use client";

import { Button } from "@cube/ui/components/button";
import { Input } from "@cube/ui/components/input";
import { Label } from "@cube/ui/components/label";
import { useRouter, useSearchParams } from "next/navigation";
import { useState } from "react";

import { login } from "@/lib/auth-client";

export function LoginForm() {
	const router = useRouter();
	const params = useSearchParams();
	const [email, setEmail] = useState("");
	const [password, setPassword] = useState("");
	const [pending, setPending] = useState(false);
	const [error, setError] = useState<string | null>(null);

	async function onSubmit(event: React.FormEvent<HTMLFormElement>) {
		event.preventDefault();
		setPending(true);
		setError(null);
		try {
			await login(email, password);
			const next = params.get("next");
			router.replace(next && next.startsWith("/") ? next : "/");
			router.refresh();
		} catch (err) {
